reemptive_AC();	// Returns true if the current MP task is preemptive. EXPORT_AC void FailIfPreemptive_AC();	// Safeguard code that must not be called from a preemptive MP task. #elseinline bool CurrentTaskIsPreemptive_AC() { return false; }inline void FailIfPreemptive_AC() {}#endif // qWantsMP#if qDebuginline void AssertNotPreemptive_AC(){	FailIfPreemptive_AC();}#elseinline void AssertNotPreemptive_AC() {}#endif#endif // __CMPFailure_AC__